const openInvoicesOfSubscription = `-- name: OpenInvoicesOfSubscription :many
SELECT id, status, provider_kind
FROM instance_invoice
WHERE instance_billing_id = $1
  AND status IN ('DRAFT', 'PUSH_FAILED', 'MANUAL', 'PUSHED', 'PAYMENT_FAILED')
ORDER BY created_at
`

type OpenInvoicesOfSubscriptionRow struct {
	ID           uuid.UUID           `json:"id"`
	Status       InvoiceStatus       `json:"status"`
	ProviderKind BillingProviderKind `json:"provider_kind"`
}

// The subscription's invoices still open, as the switch's answer lists them.
func (q *Queries) OpenInvoicesOfSubscription(ctx context.Context, instanceBillingID uuid.UUID) ([]OpenInvoicesOfSubscriptionRow, error) {
	rows, err := q.db.Query(ctx, openInvoicesOfSubscription, instanceBillingID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []OpenInvoicesOfSubscriptionRow
	for rows.Next() {
		var i OpenInvoicesOfSubscriptionRow
		if err := rows.Scan(&i.ID, &i.Status, &i.ProviderKind); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

