const upsertCustomerBilling = `-- name: UpsertCustomerBilling :exec
INSERT INTO customer_billing (customer_id, organization_id, provider_kind, external_customer_id, web_url, synced_at)
VALUES ($1, $2, $3, $4,
        $5, $6)
ON CONFLICT (customer_id, provider_kind) DO UPDATE
  SET external_customer_id = EXCLUDED.external_customer_id,
      web_url              = EXCLUDED.web_url,
      synced_at            = EXCLUDED.synced_at,
      last_error           = NULL,
      updated_at           = CURRENT_TIMESTAMP
`

type UpsertCustomerBillingParams struct {
	CustomerID         uuid.UUID           `json:"customer_id"`
	OrganizationID     uuid.UUID           `json:"organization_id"`
	ProviderKind       BillingProviderKind `json:"provider_kind"`
	ExternalCustomerID string              `json:"external_customer_id"`
	WebUrl             *string             `json:"web_url"`
	Now                pgtype.Timestamp    `json:"now"`
}

func (q *Queries) UpsertCustomerBilling(ctx context.Context, arg UpsertCustomerBillingParams) error {
	_, err := q.db.Exec(ctx, upsertCustomerBilling,
		arg.CustomerID,
		arg.OrganizationID,
		arg.ProviderKind,
		arg.ExternalCustomerID,
		arg.WebUrl,
		arg.Now,
	)
	return err
}
